@lombok.Data
@org.springframework.boot.context.properties.ConfigurationProperties(prefix = "spring.boot.admin.client")
public class ClientProperties {
    /**
     * The admin server urls to register at
     */
    private java.lang.String[] url = new java.lang.String[]{  };

    /**
     * The admin rest-apis path.
     */
    private java.lang.String apiPath = "instances";

    /**
     * Time interval the registration is repeated
     */
    @org.springframework.boot.convert.DurationUnit(java.time.temporal.ChronoUnit.MILLIS)
    private java.time.Duration period = java.time.Duration.ofMillis(10000L);

    /**
     * Connect timeout for the registration.
     */
    @org.springframework.boot.convert.DurationUnit(java.time.temporal.ChronoUnit.MILLIS)
    private java.time.Duration connectTimeout = java.time.Duration.ofMillis(5000L);

    /**
     * Read timeout (in ms) for the registration.
     */
    @org.springframework.boot.convert.DurationUnit(java.time.temporal.ChronoUnit.MILLIS)
    private java.time.Duration readTimeout = java.time.Duration.ofMillis(5000L);

    /**
     * Username for basic authentication on admin server
     */
    private java.lang.String username;

    /**
     * Password for basic authentication on admin server
     */
    private java.lang.String password;

    /**
     * Enable automatic deregistration on shutdown
     * If not set it defaults to true if a active {@link CloudPlatform} is present;
     */
    private java.lang.Boolean autoDeregistration = null;

    /**
     * Enable automatic registration when the application is ready.
     */
    private boolean autoRegistration = true;

    /**
     * Enable registration against one or all admin servers
     */
    private boolean registerOnce = true;

    /**
     * Enable Spring Boot Admin Client.
     */
    private boolean enabled = true;

    private final org.springframework.core.env.Environment environment;

    public ClientProperties(org.springframework.core.env.Environment environment) {
        org.springframework.util.Assert.notNull(environment, "Environment must not be null");
        this.environment = environment;
    }

    public java.lang.String[] getAdminUrl() {
        java.lang.String[] adminUrls = url.clone();
        for (int i = 0; i < adminUrls.length; i++) {
            adminUrls[i] += "/" + apiPath;
        }
        return adminUrls;
    }

    public boolean isAutoDeregistration() {
        return this.autoDeregistration != null ? autoDeregistration : org.springframework.boot.cloud.CloudPlatform.getActive(environment) != null;
    }
}

