/**
 * This condition checks if the client should be enabled. Two properties are checked:
 * spring.boot.admin.client.enabled and spring.boot.admin.client.url. The following table shows under which conditions the
 * client is active.
 * <pre>
 * | enabled: false | enabled: true (default) |
 * --------- | -------------- | ----------------------- |
 * url empty | inactive       | inactive                |
 * (default) |                |                         |
 * --------- | -------------- | ----------------------- |
 * url set   | inactive       | active                  |
 * </pre>
 */
public class SpringBootAdminClientEnabledCondition extends org.springframework.boot.autoconfigure.condition.SpringBootCondition {
    @java.lang.Override
    public org.springframework.boot.autoconfigure.condition.ConditionOutcome getMatchOutcome(org.springframework.context.annotation.ConditionContext context, org.springframework.core.type.AnnotatedTypeMetadata annotatedTypeMetadata) {
        de.codecentric.boot.admin.client.config.ClientProperties clientProperties = getClientProperties(context);
        if (!clientProperties.isEnabled()) {
            return org.springframework.boot.autoconfigure.condition.ConditionOutcome.noMatch("Spring Boot Client is disabled, because 'spring.boot.admin.client.enabled' is false.");
        }
        if (clientProperties.getUrl().length == 0) {
            return org.springframework.boot.autoconfigure.condition.ConditionOutcome.noMatch("Spring Boot Client is disabled, because 'spring.boot.admin.client.url' is empty.");
        }
        return org.springframework.boot.autoconfigure.condition.ConditionOutcome.match();
    }

    private de.codecentric.boot.admin.client.config.ClientProperties getClientProperties(org.springframework.context.annotation.ConditionContext context) {
        de.codecentric.boot.admin.client.config.ClientProperties clientProperties = new de.codecentric.boot.admin.client.config.ClientProperties(context.getEnvironment());
        org.springframework.boot.context.properties.bind.Binder.get(context.getEnvironment()).bind("spring.boot.admin.client", org.springframework.boot.context.properties.bind.Bindable.ofInstance(clientProperties));
        return clientProperties;
    }
}

