/**
 * Contains all informations which is used when this application is registered.
 *
 * @author Johannes Edmeier
 */
@lombok.Data
@lombok.ToString(exclude = "metadata")
public class Application {
    private final java.lang.String name;

    private final java.lang.String managementUrl;

    private final java.lang.String healthUrl;

    private final java.lang.String serviceUrl;

    private final java.util.Map<java.lang.String, java.lang.String> metadata;

    @lombok.Builder(builderClassName = "Builder")
    protected Application(java.lang.String name, java.lang.String managementUrl, java.lang.String healthUrl, java.lang.String serviceUrl, @lombok.Singular("metadata")
    java.util.Map<java.lang.String, java.lang.String> metadata) {
        org.springframework.util.Assert.hasText(name, "name must not be empty!");
        org.springframework.util.Assert.hasText(healthUrl, "healthUrl must not be empty!");
        this.name = name;
        this.managementUrl = managementUrl;
        this.healthUrl = healthUrl;
        this.serviceUrl = serviceUrl;
        this.metadata = new java.util.HashMap<>(metadata);
    }

    public static de.codecentric.boot.admin.client.registration.Builder create(java.lang.String name) {
        return de.codecentric.boot.admin.client.registration.Application.builder().name(name);
    }

    public java.util.Map<java.lang.String, java.lang.String> getMetadata() {
        return java.util.Collections.unmodifiableMap(metadata);
    }
}

