/**
 * Registers the client application at spring-boot-admin-server
 */
public class ApplicationRegistrator {
    private static final org.slf4j.Logger LOGGER = org.slf4j.LoggerFactory.getLogger(de.codecentric.boot.admin.client.registration.ApplicationRegistrator.class);

    private static final org.springframework.core.ParameterizedTypeReference<java.util.Map<java.lang.String, java.lang.Object>> RESPONSE_TYPE = new org.springframework.core.ParameterizedTypeReference<java.util.Map<java.lang.String, java.lang.Object>>() {};

    private static final org.springframework.http.HttpHeaders HTTP_HEADERS = de.codecentric.boot.admin.client.registration.ApplicationRegistrator.createHttpHeaders();

    private final java.util.concurrent.ConcurrentHashMap<java.lang.String, java.util.concurrent.atomic.LongAdder> attempts = new java.util.concurrent.ConcurrentHashMap<>();

    private final java.util.concurrent.atomic.AtomicReference<java.lang.String> registeredId = new java.util.concurrent.atomic.AtomicReference<>();

    private final de.codecentric.boot.admin.client.config.ClientProperties client;

    private final org.springframework.web.client.RestTemplate template;

    private final de.codecentric.boot.admin.client.registration.ApplicationFactory applicationFactory;

    public ApplicationRegistrator(org.springframework.web.client.RestTemplate template, de.codecentric.boot.admin.client.config.ClientProperties client, de.codecentric.boot.admin.client.registration.ApplicationFactory applicationFactory) {
        this.client = client;
        this.template = template;
        this.applicationFactory = applicationFactory;
    }

    private static org.springframework.http.HttpHeaders createHttpHeaders() {
        org.springframework.http.HttpHeaders headers = new org.springframework.http.HttpHeaders();
        headers.setContentType(org.springframework.http.MediaType.APPLICATION_JSON);
        headers.setAccept(java.util.Collections.singletonList(org.springframework.http.MediaType.APPLICATION_JSON));
        return org.springframework.http.HttpHeaders.readOnlyHttpHeaders(headers);
    }

    /**
     * Registers the client application at spring-boot-admin-server.
     *
     * @return true if successful registration on at least one admin server
     */
    public boolean register() {
        de.codecentric.boot.admin.client.registration.Application self = createApplication();
        boolean isRegistrationSuccessful = false;
        for (java.lang.String adminUrl : client.getAdminUrl()) {
            java.util.concurrent.atomic.LongAdder attempt = this.attempts.computeIfAbsent(adminUrl, k -> new java.util.concurrent.atomic.LongAdder());
            boolean successful = register(self, adminUrl, attempt.intValue() == 0);
            if (!successful) {
                attempt.increment();
            } else {
                attempt.reset();
                isRegistrationSuccessful = true;
                if (client.isRegisterOnce()) {
                    break;
                }
            }
        }
        return isRegistrationSuccessful;
    }

    protected boolean register(de.codecentric.boot.admin.client.registration.Application self, java.lang.String adminUrl, boolean firstAttempt) {
        try {
            org.springframework.http.ResponseEntity<java.util.Map<java.lang.String, java.lang.Object>> response = template.exchange(adminUrl, org.springframework.http.HttpMethod.POST, new org.springframework.http.HttpEntity<>(self, de.codecentric.boot.admin.client.registration.ApplicationRegistrator.HTTP_HEADERS), de.codecentric.boot.admin.client.registration.ApplicationRegistrator.RESPONSE_TYPE);
            if (response.getStatusCode().is2xxSuccessful()) {
                if (registeredId.compareAndSet(null, response.getBody().get("id").toString())) {
                    de.codecentric.boot.admin.client.registration.ApplicationRegistrator.LOGGER.info("Application registered itself as {}", response.getBody().get("id").toString());
                } else {
                    de.codecentric.boot.admin.client.registration.ApplicationRegistrator.LOGGER.debug("Application refreshed itself as {}", response.getBody().get("id").toString());
                }
                return true;
            } else if (firstAttempt) {
                de.codecentric.boot.admin.client.registration.ApplicationRegistrator.LOGGER.warn("Application failed to registered itself as {}. Response: {}. Further attempts are logged on DEBUG level", self, response.toString());
            } else {
                de.codecentric.boot.admin.client.registration.ApplicationRegistrator.LOGGER.debug("Application failed to registered itself as {}. Response: {}", self, response.toString());
            }
        } catch (java.lang.Exception ex) {
            if (firstAttempt) {
                de.codecentric.boot.admin.client.registration.ApplicationRegistrator.LOGGER.warn("Failed to register application as {} at spring-boot-admin ({}): {}. Further attempts are logged on DEBUG level", self, client.getAdminUrl(), ex.getMessage());
            } else {
                de.codecentric.boot.admin.client.registration.ApplicationRegistrator.LOGGER.debug("Failed to register application as {} at spring-boot-admin ({}): {}", self, client.getAdminUrl(), ex.getMessage());
            }
        }
        return false;
    }

    public void deregister() {
        java.lang.String id = registeredId.get();
        if (id != null) {
            for (java.lang.String adminUrl : client.getAdminUrl()) {
                try {
                    template.delete((adminUrl + "/") + id);
                    registeredId.compareAndSet(id, null);
                    if (client.isRegisterOnce()) {
                        break;
                    }
                } catch (java.lang.Exception ex) {
                    de.codecentric.boot.admin.client.registration.ApplicationRegistrator.LOGGER.warn("Failed to deregister application (id={}) at spring-boot-admin ({}): {}", id, adminUrl, ex.getMessage());
                }
            }
        }
    }

    /**
     *
     * @return the id of this client as given by the admin server.
    Returns null if the client has not registered against the admin server yet.
     */
    public java.lang.String getRegisteredId() {
        return registeredId.get();
    }

    protected de.codecentric.boot.admin.client.registration.Application createApplication() {
        return applicationFactory.createApplication();
    }
}

