/**
 * Listener responsible for starting and stopping the registration task when the application is
 * ready.
 *
 * @author Johannes Edmeier
 */
public class RegistrationApplicationListener implements org.springframework.beans.factory.InitializingBean , org.springframework.beans.factory.DisposableBean {
    private static final org.slf4j.Logger LOGGER = org.slf4j.LoggerFactory.getLogger(de.codecentric.boot.admin.client.registration.RegistrationApplicationListener.class);

    private final de.codecentric.boot.admin.client.registration.ApplicationRegistrator registrator;

    private final org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler taskScheduler;

    private boolean autoDeregister = false;

    private boolean autoRegister = true;

    private java.time.Duration registerPeriod = java.time.Duration.ofSeconds(10);

    private volatile java.util.concurrent.ScheduledFuture<?> scheduledTask;

    public RegistrationApplicationListener(de.codecentric.boot.admin.client.registration.ApplicationRegistrator registrator) {
        this(registrator, de.codecentric.boot.admin.client.registration.RegistrationApplicationListener.registrationTaskScheduler());
    }

    private static org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler registrationTaskScheduler() {
        org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler taskScheduler = new org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler();
        taskScheduler.setPoolSize(1);
        taskScheduler.setRemoveOnCancelPolicy(true);
        taskScheduler.setThreadNamePrefix("registrationTask");
        return taskScheduler;
    }

    RegistrationApplicationListener(de.codecentric.boot.admin.client.registration.ApplicationRegistrator registrator, org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler taskScheduler) {
        this.registrator = registrator;
        this.taskScheduler = taskScheduler;
    }

    @org.springframework.context.event.EventListener
    @org.springframework.core.annotation.Order(org.springframework.core.Ordered.LOWEST_PRECEDENCE)
    public void onApplicationReady(org.springframework.boot.context.event.ApplicationReadyEvent event) {
        if (autoRegister) {
            startRegisterTask();
        }
    }

    @org.springframework.context.event.EventListener
    @org.springframework.core.annotation.Order(org.springframework.core.Ordered.LOWEST_PRECEDENCE)
    public void onClosedContext(org.springframework.context.event.ContextClosedEvent event) {
        if ((event.getApplicationContext().getParent() == null) || "bootstrap".equals(event.getApplicationContext().getParent().getId())) {
            stopRegisterTask();
            if (autoDeregister) {
                registrator.deregister();
            }
        }
    }

    public void startRegisterTask() {
        if ((scheduledTask != null) && (!scheduledTask.isDone())) {
            return;
        }
        scheduledTask = taskScheduler.scheduleAtFixedRate(registrator::register, registerPeriod);
        de.codecentric.boot.admin.client.registration.RegistrationApplicationListener.LOGGER.debug("Scheduled registration task for every {}ms", registerPeriod);
    }

    public void stopRegisterTask() {
        if ((scheduledTask != null) && (!scheduledTask.isDone())) {
            scheduledTask.cancel(true);
            de.codecentric.boot.admin.client.registration.RegistrationApplicationListener.LOGGER.debug("Canceled registration task");
        }
    }

    public void setAutoDeregister(boolean autoDeregister) {
        this.autoDeregister = autoDeregister;
    }

    public void setAutoRegister(boolean autoRegister) {
        this.autoRegister = autoRegister;
    }

    public void setRegisterPeriod(java.time.Duration registerPeriod) {
        this.registerPeriod = registerPeriod;
    }

    @java.lang.Override
    public void afterPropertiesSet() {
        taskScheduler.afterPropertiesSet();
    }

    @java.lang.Override
    public void destroy() {
        taskScheduler.destroy();
    }
}

