public class CompositeMetadataContributor implements de.codecentric.boot.admin.client.registration.metadata.MetadataContributor {
    private final java.util.List<de.codecentric.boot.admin.client.registration.metadata.MetadataContributor> delegates;

    public CompositeMetadataContributor(java.util.List<de.codecentric.boot.admin.client.registration.metadata.MetadataContributor> delegates) {
        this.delegates = delegates;
    }

    @java.lang.Override
    public java.util.Map<java.lang.String, java.lang.String> getMetadata() {
        java.util.Map<java.lang.String, java.lang.String> metadata = new java.util.LinkedHashMap<>();
        delegates.forEach(delegate -> metadata.putAll(delegate.getMetadata()));
        return metadata;
    }
}

