    java.util.concurrent.atomic.LongAdder attempt = this.attempts.computeIfAbsent(adminUrl, k -> new java.util.concurrent.atomic.LongAdder());
    boolean successful = register(self, adminUrl, attempt.intValue() == 0);
    if (!successful) {
        attempt.increment();
    } else {
        attempt.reset();
        isRegistrationSuccessful = true;
        if (client.isRegisterOnce()) {
            break;
        }
    }
